/**
 * @file src/lib/towerQuest.ts
 * Detects quests tied to the Battle Tower game mode (floor / record objectives).
 * Lore quests that merely contain "tower" in their id (Burned Tower, Lost Tower,
 * Celestial Tower, Pokémon Tower…) are zone quests and must NOT match.
 */

const TOWER_TRACKING_KEYS = new Set(['tower_floor', 'towerFloor', 'towerRecord']);

export function isBattleTowerQuest(
  quest: { id?: string | number; trackingKey?: string } | null | undefined,
): boolean {
  if (!quest) return false;
  if (typeof quest.trackingKey === 'string' && TOWER_TRACKING_KEYS.has(quest.trackingKey)) return true;
  return typeof quest.id === 'string' && /^story_tower_/.test(quest.id);
}
